## Submitted testbench
```systemverilog
module tb;

  // Clock and reset
  logic                     clk = 0;
  logic                     rst = 0;

  // Timing and configuration
  localparam int            CLK_PERIOD = 8;               // 125 MHz
  logic [15:0]              prescale_val = 16'd5;

  // AXI‑Stream inputs
  logic [7:0]               s_axis_tdata;
  logic                     s_axis_tvalid;
  // AXI‑Stream outputs (tied off)
  assign s_axis_tready      = 1'b1;                      // always ready
  assign txd                = 1'b0;
  logic                     tx_busy;
  logic                     rx_busy;
  logic                     rx_overrun_error;
  logic                     rx_frame_error;
  assign tx_busy            = 1'b0;
  assign rx_busy            = 1'b0;
  assign rx_overrun_error   = 1'b0;
  assign rx_frame_error     = 1'b0;

  // UART interface
  logic                     rxd;                       // driven by testbench
  logic [7:0]               m_axis_tdata;
  logic                     m_axis_tvalid;
  logic                     m_axis_tready;              // forced low

  // Tie m_axis_tready to constant 0 (never handshake)
  assign m_axis_tready      = 1'b0;

  // Instantiate the DUT (default parameter values)
  uart dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .rxd               (rxd),
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale_val)
  );

  // ------------------------------------------------------------
  // Clock generation
  initial begin
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

  // ------------------------------------------------------------
  // Reset sequence
  initial begin
    rst = 0;
    #100ns;
    rst = 1;
    #100ns;
    rst = 0;
    #100ns;
  end

  // ------------------------------------------------------------
  // Task to transmit a byte on rxd (8N1, LSB‑first)
  task automatic uart_send_byte(input byte unsigned b);
    int unsigned bit_clks = int'(prescale_val) * 8;
    // start bit
    rxd = 0;
    repeat (bit_clks) @(negedge clk);
    // data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      repeat (bit_clks) @(negedge clk);
    end
    // stop bit
    rxd = 1;
    repeat (bit_clks) @(negedge clk);
  endtask

  // ------------------------------------------------------------
  // Stimulus
  initial begin
    // Wait until reset is released
    wait (rst == 0);

    // Send first arbitrary byte (does not matter)
    uart_send_byte(8'hA5);
    #500ns;  // small idle gap

    // Send second byte whose data is 0x5A – this is the third word
    // that triggers the double‑overrun coverage point.
    uart_send_byte(8'h5A);
    // Allow enough cycles for the coverage assertion to be evaluated
    repeat (500) @(negedge clk);

    // End simulation cleanly
    $finish;
  end

endmodule
